package dev.hoi.protocol.commander;

import dev.hoi.protocol.industry.IndustryTankDesigner;
import java.util.*;
import static dev.hoi.protocol.industry.IndustryView.*;

public record CommanderArmyHeadquarters(List<Template> templates,Template draft,boolean copy,boolean dirty,String saveReason,int armies,Map<String,String> labels,List<Slot> slots,Details details,int experience) {
    public CommanderArmyHeadquarters(List<Template> templates,Template draft,boolean copy,boolean dirty,String saveReason,int armies,Map<String,String> labels,List<Slot> slots,Details details){this(templates,draft,copy,dirty,saveReason,armies,labels,slots,details,0);}
    public CommanderArmyHeadquarters(List<Template> templates,Template draft,boolean copy,boolean dirty,String saveReason,int armies,Map<String,String> labels,List<Slot> slots){this(templates,draft,copy,dirty,saveReason,armies,labels,slots,null);}
    public CommanderArmyHeadquarters {slots=slots==null?List.of():bounded(slots,8);labels=labels==null?Map.of():Map.copyOf(labels);if(labels.size()>128)throw new IllegalArgumentException("HQ labels too large");labels.forEach((key,value)->{text(key,128);text(value,256);});templates=bounded(templates,128);text(saveReason,2048);if(armies<0||experience<0)throw new IllegalArgumentException("Invalid HQ army count");}
    private static <T> List<T> bounded(List<T> values,int max){if(values==null||values.size()>max)throw new IllegalArgumentException("HQ view too large");return List.copyOf(values);}
    public record Details(Map<String,String> units,String leaderBenefits,double baseHitpoints,List<IndustryTankDesigner.Adjustment> adjustments,List<IndustryTankDesigner.Stat> stats){public Details(Map<String,String> units,String leaderBenefits,double baseHitpoints,List<IndustryTankDesigner.Adjustment> adjustments){this(units,leaderBenefits,baseHitpoints,adjustments,List.of());}public Details(Map<String,String> units,String leaderBenefits,double baseHitpoints){this(units,leaderBenefits,baseHitpoints,List.of());}public Details{stats=stats==null?List.of():bounded(stats,32);adjustments=adjustments==null?List.of():bounded(adjustments,11);if(new HashSet<>(adjustments.stream().map(IndustryTankDesigner.Adjustment::id).toList()).size()!=adjustments.size())throw new IllegalArgumentException("Duplicate HQ terrain");units=Map.copyOf(units);if(units.size()>32||!Double.isFinite(baseHitpoints)||baseHitpoints<0)throw new IllegalArgumentException("Invalid HQ details");units.forEach((key,value)->{text(key,80);text(value,3000);});text(leaderBenefits,3000);}}
    public record Choice(String id,String reason,long manpower,Map<String,Long> equipment,double baseCommandPower,List<IndustryTankDesigner.Stat> changes,String tooltip,String group,int experience) {
        public Choice(String id,String reason,long manpower,Map<String,Long> equipment,double baseCommandPower,List<IndustryTankDesigner.Stat> changes,String tooltip){this(id,reason,manpower,equipment,baseCommandPower,changes,tooltip,"",0);}
        public Choice(String id,String reason,long manpower,Map<String,Long> equipment,double baseCommandPower,List<IndustryTankDesigner.Stat> changes){this(id,reason,manpower,equipment,baseCommandPower,changes,"");}
        public Choice(String id,String reason,long manpower,Map<String,Long> equipment,double baseCommandPower){this(id,reason,manpower,equipment,baseCommandPower,List.of());}
        public Choice {tooltip=tooltip==null?"":tooltip;group=group==null?"":group;text(group,32);text(tooltip,4096);changes=changes==null?List.of():bounded(changes,32);text(id,80);text(reason,512);equipment=Map.copyOf(equipment);if(equipment.size()>32||equipment.values().stream().anyMatch(v->v<0)||manpower<0||!Double.isFinite(baseCommandPower)||baseCommandPower<0)throw new IllegalArgumentException("Invalid HQ candidate");equipment.keySet().forEach(v->text(v,128));}
    }
    public record Slot(boolean support,int index,String current,String reason,List<Choice> choices,String tooltip,Map<String,Integer> groups) {
        public Slot(boolean support,int index,String current,String reason,List<Choice> choices,String tooltip){this(support,index,current,reason,choices,tooltip,Map.of());}
        public Slot(boolean support,int index,String current,String reason,List<Choice> choices){this(support,index,current,reason,choices,"");}
        public Slot {groups=groups==null?Map.of():Map.copyOf(groups);if(groups.size()>8||groups.values().stream().anyMatch(v->v<0))throw new IllegalArgumentException("Invalid HQ groups");groups.keySet().forEach(v->text(v,32));tooltip=tooltip==null?"":tooltip;text(tooltip,4096);if(index<0||index>=4)throw new IllegalArgumentException("Invalid HQ slot");text(current,80);text(reason,512);choices=bounded(choices,32);}
    }
    public record Template(String id,String name,long version,List<String> battalions,List<String> support,long manpower,Map<String,Long> equipment,double baseCommandPower,int deployDays,double costMinimum,double costMaximum,List<String> resources,int priority,boolean paradrop,String paradropTooltip,int specialForces,String specialForcesTooltip) {
        public Template(String id,String name,long version,List<String> battalions,List<String> support,long manpower,Map<String,Long> equipment,double baseCommandPower,int deployDays,double costMinimum,double costMaximum,List<String> resources){this(id,name,version,battalions,support,manpower,equipment,baseCommandPower,deployDays,costMinimum,costMaximum,resources,1,false,"",0,"");}
        public Template(String id,String name,long version,List<String> battalions,List<String> support,long manpower,Map<String,Long> equipment,double baseCommandPower){this(id,name,version,battalions,support,manpower,equipment,baseCommandPower,0,0,0,List.of());}
        public Template {paradropTooltip=paradropTooltip==null?"":paradropTooltip;specialForcesTooltip=specialForcesTooltip==null?"":specialForcesTooltip;text(paradropTooltip,4096);text(specialForcesTooltip,4096);if(priority<0||priority>2||specialForces<0||specialForces>8)throw new IllegalArgumentException("Invalid HQ template settings");resources=resources==null?List.of():bounded(resources,8);resources.forEach(v->text(v,32));if(deployDays<0||deployDays>3650||!Double.isFinite(costMinimum)||!Double.isFinite(costMaximum)||costMinimum<0||costMaximum<costMinimum)throw new IllegalArgumentException("Invalid HQ template cost");text(id,128);text(name,80);battalions=bounded(battalions,4);support=bounded(support,4);battalions.forEach(v->text(v,80));support.forEach(v->text(v,80));equipment=Map.copyOf(equipment);if(equipment.size()>32||equipment.values().stream().anyMatch(v->v<0)||version<1||manpower<0||!Double.isFinite(baseCommandPower)||baseCommandPower<0)throw new IllegalArgumentException("Invalid HQ template view");equipment.keySet().forEach(v->text(v,128));}
    }
}
